def create_header(self):
    """Create a new :py:class:`hl7.Segment` FHS compatible with this file"""
    return self.create_segment(
        [
            self.create_field(["FHS"]),
            self.create_field([self.separators[1]]),
            self.create_field(
                [
                    self.separators[3]
                    + self.separators[2]
                    + self.esc
                    + self.separators[4]
                ]
            ),
        ]
    )

